<template>
    <div>test</div>
    <div v-for="article in articles" v-bind:key="article.url" id="articles">
        <div>
            <span
                  v-for="tag in article.tags" 
                  v-bind:key="tag" 
                  class="tag"
            >
                {{ tag }}
            </span>
        </div>
        <div>
         <strong>Category:</strong> {{ article.category.title }} <!-- 显示分类标题 -->
         </div>
        <router-link
            :to="{ name: 'ArticleDetail', params: { id: extractId(article.url) }}"
            class="article-title"
        >
            {{ article.title }}
        </router-link>
        <div>{{ formatted_time(article.created) }}</div>
    </div>
</template>

<script>
    import axios from 'axios';

    export default {
        name: 'ArticleList',
        data() {
            return {
                articles: [] // 修改为数组
            }
        },
        
        mounted() {
            axios
                .get('/api/article')
                .then(response => {
                    // 假设API返回的数据是一个数组
                    this.articles = response.data.results || response.data; // 根据实际数据结构调整
                    console.log("这里开始");
                    console.log(this.articles); // 检查数据结构
                    console.log("这里结束");
                })
                .catch(error => {
                    console.error("API请求失败：", error);
                });
        },
        methods: {
            formatted_time(iso_date_string) {
                const date = new Date(iso_date_string);
                return date.toLocaleDateString();
            },
            extractId(url) {
                const match = url.match(/\/api\/article\/(\d+)\//);
                return match ? match[1] : null;
            }
        }
    }
</script>

<style scoped>
    #articles {
        padding: 10px;
    }

    .article-title {
        font-size: large;
        font-weight: bolder;
        color: black;
        text-decoration: none;
        padding: 5px 0 5px 0;
    }

    .tag {
        padding: 2px 5px;
        margin: 5px 5px 5px 0;
        font-family: Georgia, Arial, sans-serif;
        font-size: small;
        background-color: #4e4e4e;
        color: whitesmoke;
        border-radius: 5px;
    }
</style>
