<template>
  <div v-if="article">
    <h1>{{ article.title }}</h1>
    <div>
      <span v-for="tag in article.tags" :key="tag" class="tag">
        {{ tag }}
      </span>
    </div>
    <div class="article-meta">
      <span>创建时间: {{ formattedTime(article.created) }}</span>
    </div>
    <div v-html="article.body" class="article-body"></div>
  </div>
  <div v-else>
    <p>加载中...</p>
  </div>
</template>

<script>
import axios from 'axios';

export default {
  name: 'ArticleDetail',
  data() {
    return {
      article: null,
    };
  },
  created() {
    this.fetchArticle();
  },
  methods: {
    fetchArticle() {
      const articleId = this.$route.params.id;
      axios
        .get(`/api/article/${articleId}/`)
        .then(response => {
          this.article = response.data;
        })
        .catch(error => {
          console.error("无法获取文章详情：", error);
        });
    },
    formattedTime(isoDateString) {
      const date = new Date(isoDateString);
      return date.toLocaleDateString();
    },
  },
};
</script>

